CREATE TABLE atlys_dataset.reminder_sent (`id` FixedString(32) COMMENT 'event id, 32-char hex, high cardinality' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/android/web-user-b2c/Desktop, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT 'os name; ~5% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version, 3 values', `geoip_country_code` LowCardinality(String) COMMENT 'geo country code, 7 values', `city` LowCardinality(String) COMMENT 'geo city, 7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'application id, links recovery funnel stages' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'destination country, 14 values', `drop_step` LowCardinality(String) COMMENT 'funnel step the nudge targets, 4 values', `channel` LowCardinality(String) COMMENT 'nudge channel: push/email/whatsapp', `hours_since_drop` UInt8 COMMENT 'delay before send, hours, range 1-48' CODEC(T64, ZSTD(1)), INDEX idx_user_id user_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (drop_step, channel, hours_since_drop, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'reminder_sent: a recovery nudge is sent; step 2, carries channel and send-delay for timing analysis'
CREATE TABLE atlys_dataset.abandonment_detected (`id` FixedString(32) COMMENT 'event id, 32-char hex, high cardinality' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/android/web-user-b2c/Desktop, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT 'os name; ~5% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version, 3 values', `geoip_country_code` LowCardinality(String) COMMENT 'geo country code, 7 values', `city` LowCardinality(String) COMMENT 'geo city, 7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'application id, links recovery funnel stages' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'destination country, 14 values', `drop_step` LowCardinality(String) COMMENT 'funnel step where drop was detected, 4 values', INDEX idx_user_id user_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (drop_step, device_type, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'abandonment_detected: a funnel drop is detected; step 1 of recovery funnel (Abandoned Checkout Recovery)'
CREATE TABLE atlys_dataset.reconverted (`id` FixedString(32) COMMENT 'event id, 32-char hex, high cardinality' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/android/web-user-b2c/Desktop, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT 'os name; ~4.3% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version, 3 values', `geoip_country_code` LowCardinality(String) COMMENT 'geo country code, 7 values', `city` LowCardinality(String) COMMENT 'geo city, 7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'application id, links recovery funnel stages' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'destination country, 14 values', `drop_step` LowCardinality(String) COMMENT 'funnel step the recovered user had dropped at, 4 values', `channel` LowCardinality(String) COMMENT 'nudge channel credited with the reconversion', INDEX idx_user_id user_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (drop_step, channel, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'reconverted: payment completed after a nudge; step 6, terminal event for recovery-rate by drop_step/channel'
CREATE TABLE atlys_dataset.reminder_cta_clicked (`id` FixedString(32) COMMENT 'event id, 32-char hex, high cardinality' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/android/web-user-b2c/Desktop, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT 'os name; ~3.7% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version, 3 values', `geoip_country_code` LowCardinality(String) COMMENT 'geo country code, 7 values', `city` LowCardinality(String) COMMENT 'geo city, 7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'application id, links recovery funnel stages' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'destination country, 14 values', `drop_step` LowCardinality(String) COMMENT 'funnel step the nudge targeted, 4 values', `channel` LowCardinality(String) COMMENT 'nudge channel: push/email/whatsapp', INDEX idx_user_id user_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (drop_step, channel, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'reminder_cta_clicked: user taps the nudge CTA; step 4, click-through by channel/step'
CREATE TABLE atlys_dataset.reminder_opened (`id` FixedString(32) COMMENT 'event id, 32-char hex, high cardinality' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/android/web-user-b2c/Desktop, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT 'os name; ~4.9% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version, 3 values', `geoip_country_code` LowCardinality(String) COMMENT 'geo country code, 7 values', `city` LowCardinality(String) COMMENT 'geo city, 7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'application id, links recovery funnel stages' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'destination country, 14 values', `drop_step` LowCardinality(String) COMMENT 'funnel step the nudge targeted, 4 values', `channel` LowCardinality(String) COMMENT 'nudge channel: push/email/whatsapp', INDEX idx_user_id user_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (drop_step, channel, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'reminder_opened: the recovery nudge is opened; step 3, feeds open-rate by channel/step'
CREATE TABLE atlys_dataset.resumed_at_step (`id` FixedString(32) COMMENT 'event id, 32-char hex, high cardinality' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/android/web-user-b2c/Desktop, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT 'os name; ~3.7% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT 'client app version, 3 values', `geoip_country_code` LowCardinality(String) COMMENT 'geo country code, 7 values', `city` LowCardinality(String) COMMENT 'geo city, 7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'application id, links recovery funnel stages' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT 'destination country, 14 values', `drop_step` LowCardinality(String) COMMENT 'funnel step user resumed at, 4 values', `channel` LowCardinality(String) COMMENT 'nudge channel that drove the resume', INDEX idx_user_id user_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (drop_step, channel, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'resumed_at_step: user returns to the funnel after a nudge; step 5, bridges recovery to purchase'